CREATE DATABASE IF NOT EXISTS dcms CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE dcms;
DROP TABLE IF EXISTS cross_selling;
CREATE TABLE cross_selling (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  source_period VARCHAR(7) NOT NULL DEFAULT '2026-10',
  cabang VARCHAR(30), info VARCHAR(100), keterangan VARCHAR(100), group_name VARCHAR(150),
  posting_date DATE, waktu VARCHAR(20), document_number VARCHAR(40),
  customer_vendor_code VARCHAR(50), customer_vendor_name VARCHAR(200),
  item_code VARCHAR(100), description VARCHAR(255), item_group_name VARCHAR(100),
  brand VARCHAR(100), warehouse_code VARCHAR(100), quantity DECIMAL(18,4) DEFAULT 0,
  selling_price DECIMAL(18,2) DEFAULT 0, price_before_discount DECIMAL(18,2) DEFAULT 0,
  discount_difference DECIMAL(18,2) DEFAULT 0, p_bonus DECIMAL(18,2) DEFAULT 0,
  p_voucher DECIMAL(18,2) DEFAULT 0, p_nego DECIMAL(18,2) DEFAULT 0, p_leasing DECIMAL(18,2) DEFAULT 0,
  p_program DECIMAL(18,2) DEFAULT 0, p_edc DECIMAL(18,2) DEFAULT 0,
  p_authorization_posvit DECIMAL(18,2) DEFAULT 0, price_list VARCHAR(100),
  remarks TEXT, schl_code VARCHAR(100), sales_employee_name VARCHAR(150),
  promo VARCHAR(150), user_input VARCHAR(150), customer_phone VARCHAR(30),
  cost_price DECIMAL(18,2) DEFAULT 0, gross_profit DECIMAL(18,2) DEFAULT 0,
  reseller VARCHAR(150), leasing_subsidy DECIMAL(18,2) DEFAULT 0,
  customer_transaction VARCHAR(100), name VARCHAR(150), reference_number VARCHAR(100),
  purchase_order_number VARCHAR(100), source_file VARCHAR(255), source_row BIGINT UNSIGNED,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_cross_selling_period (source_period), INDEX idx_cross_selling_branch (cabang),
  INDEX idx_cross_selling_customer (customer_vendor_code), INDEX idx_cross_selling_document (document_number),
  INDEX idx_cross_selling_date (posting_date), INDEX idx_cross_selling_item (item_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;




















































































































































